using System;
using System.Data;
using System.Drawing;
using System.Windows.Forms;

public ExampleForm()
{
    Text = "DataGridView example";
    ClientSize = new Size(420, 240);
    InitializeComponents();
}

DataTable table = new DataTable();
table.Columns.Add("Customer", typeof(string));
table.Columns.Add("Quantity", typeof(int));
table.Rows.Add("Alice", 3);
table.Rows.Add("Bob", 5);
table.Rows.Add("Carla", 2);

dgvOrders.DataSource = table;
dgvOrders.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;
dgvOrders.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
dgvOrders.AllowUserToAddRows = false;

private void DgvOrders_SelectionChanged(object sender, EventArgs e)
{
    if (dgvOrders.CurrentRow != null)
    {
        Text = "Customer: " + dgvOrders.CurrentRow.Cells["Customer"].Value;
    }
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

using System;
using System.Data;
using System.Drawing;
using System.Windows.Forms;

private DataGridView dgvOrders;
private TextBox txtCustomer;
private Button btnNext;
private BindingSource bindingSource1;

public ExampleForm()
{
    Text = "BindingSource example";
    ClientSize = new Size(360, 200);
    InitializeComponents();
}

DataTable table = new DataTable();
table.Columns.Add("Customer", typeof(string));
table.Columns.Add("City", typeof(string));
table.Rows.Add("Alice", "Paris");
table.Rows.Add("Bob", "Rome");
table.Rows.Add("Carla", "Oslo");

dgvOrders = new DataGridView();
dgvOrders.Location = new Point(20, 20);
dgvOrders.Size = new Size(300, 120);
dgvOrders.DataSource = bindingSource1;

txtCustomer = new TextBox();
txtCustomer.Location = new Point(20, 150);
txtCustomer.DataBindings.Add("Text", bindingSource1, "Customer");

btnNext = new Button();
btnNext.Text = "Next";
btnNext.Location = new Point(140, 148);
btnNext.Click += BtnNext_Click;

Controls.Add(dgvOrders);
Controls.Add(txtCustomer);
Controls.Add(btnNext);

private void BtnNext_Click(object sender, EventArgs e)
{
    bindingSource1.MoveNext();
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

